for (const [key, correction] of Object.entries(YOKOHAMA_DETAIL_CORRECTIONS)) {
  const detail = YOKOHAMA_MUTABLE_DETAILS[key];
  if (!detail) throw new Error(`Unknown Yokohama detail correction key: ${key}`);
  if (correction.description) {
    detail.description = { ...detail.description, ...correction.description };
  }
  if (correction.standards !== undefined) detail.standards = correction.standards;
}

function buildLocalizedUsageFeatures(text: string): string[] {
  const protectedText = text.replace(/\bU\.S\./g, "U§S§");
  return protectedText
    .split(/(?<=[.!?؟])\s+(?=[\p{Lu}\p{Lt}\p{Script=Arabic}])/gu)
    .map((feature) => feature.replace(/U§S§/g, "U.S.").trim())
    .filter(Boolean);
}

for (const detail of Object.values(YOKOHAMA_MUTABLE_DETAILS)) {
  detail.features = Object.fromEntries(
    YOKOHAMA_DETAIL_LOCALES.map((locale) => [
      locale,
      buildLocalizedUsageFeatures(detail.description[locale]),
    ]),
  ) as YokohamaLocalizedTextArray;
}
